svg.script:

let workTime = 25 * 60;
let breakTime = 5 * 60;
let currentTime = workTime;
let isWorkMode = true;
let timerId = null;

function formatTime(sec) {
    let m = Math.floor(sec / 60).toString().padStart(2, '0');
    let s = (sec % 60).toString().padStart(2, '0');
    return m + ":" + s;
}

function updateDisplay() {
    document.getElementById('timerDisplay').textContent = formatTime(currentTime);

    let total = isWorkMode ? workTime : breakTime;
    let progressWidth = ((total - currentTime) / total) * 280;
    document.getElementById('progressBar').setAttribute('width', progressWidth);
}

function toggleTimer() {
    let btnText = document.getElementById('startBtnText');
    if (timerId) {
        clearInterval(timerId);
        timerId = null;
        btnText.textContent = "Devam Et";
    } else {
        btnText.textContent = "Duraklat";
        timerId = setInterval(() => {
            if (currentTime > 0) {
                currentTime--;
                updateDisplay();
            } else {
                isWorkMode = !isWorkMode;
                currentTime = isWorkMode ? workTime : breakTime;

                let statusText = document.getElementById('statusText');
                statusText.textContent = isWorkMode ? "ODAKLANMA ZAMANI" : "MOLA ZAMANI";
                statusText.setAttribute('fill', isWorkMode ? "#7ee787" : "#58a6ff");

                updateDisplay();
            }
        }, 1000);
    }
}

function resetTimer() {
    if (timerId) {
        clearInterval(timerId);
        timerId = null;
    }
    isWorkMode = true;
    currentTime = workTime;
    document.getElementById('startBtnText').textContent = "Başlat";
    document.getElementById('statusText').textContent = "ODAKLANMA ZAMANI";
    document.getElementById('statusText').setAttribute('fill', "#7ee787");
    updateDisplay();
}
